const input = items[0]?.json || {};

return [
 {
   json: {
     ...input,
     m11_config: {
       service_name: 'DALIA_M11_Demo_Validation_Runner',
       service_version: 'v1',

       environment: 'demo',

       /*
        * Opciones:
        * manual_evidence: tú ejecutas los mensajes por WhatsApp/Telegram y M11 evalúa logs.
        * webhook: M11 intenta enviar los mensajes a un webhook principal de entrada.
        */
       execution_mode: 'manual_evidence',

       /*
        * Si usas modo webhook, reemplaza esta URL.
        */
       main_entry_webhook_url: 'REEMPLAZAR_WEBHOOK_PRINCIPAL_DALIA',

       test_context: {
         business_id: 'business_demo',
         channel: 'wa', // Cambiado a 'wa' para que coincida con tus logs
         bot_id: '1104496126080610', // ¡Nueva variable dinámica agregada!
         user_id: '573108058407', // Tu número real de pruebas
         display_name: 'Tester Demo'
       },

       validation_policy: {
         wait_seconds_after_case: 8,
         evidence_window_minutes: 60,
         fail_on_critical_error_events: true
       },

       storage: {
         validation_runs_table: 'dalia_demo_validation_runs',
         validation_results_table: 'dalia_demo_validation_results',
         observability_events_table: 'dalia_observability_events_lite'
       }
     }
   }
 }
];

function makeId(prefix) {
 const ts = Date.now();
 const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
 return `${prefix}_${ts}_${rand}`;
}

const input = items[0]?.json || {};
const config = input.m11_config || {};

const now = new Date().toISOString();

const validationRun = {
 validation_run_id: makeId('valrun_demo'),
 environment: config.environment || 'demo',
 execution_mode: config.execution_mode || 'manual_evidence',
 status: 'running',

 started_at: now,
 finished_at: null,

 total_cases: 5,
 passed_cases: 0,
 warning_cases: 0,
 failed_cases: 0,

 go_no_go: '',
 summary: '',

 metadata: {
   service_name: config.service_name,
   service_version: config.service_version,
   test_context: config.test_context,
   validation_policy: config.validation_policy,
   created_at: now
 }
};

return [
 {
   json: {
     ...input,
     validation_run: validationRun
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

const base = $('Build Validation Run Draft').first().json || {};
const config = base.m11_config || {};
const run = base.validation_run || {};

const ctx = config.test_context || {};

// 1. Extraemos las variables limpias desde la configuración (cero datos quemados)
const channel = clean(ctx.channel || 'wa');
const userPhone = clean(ctx.user_id || '');
const botId = clean(ctx.bot_id || '');

// 2. Construimos los IDs dinámicamente tal como los guarda tu bot
const userId = `${channel}_demo_${botId}_${userPhone}`;
const conversationId = `conv_${channel}_${botId}_${userPhone}`;
const sessionId = `${channel}_demo_${botId}_${userPhone}`;

const commonTrace = {
 conversation_id: conversationId,
 session_id: sessionId
};

const commonContext = {
 business_id: ctx.business_id || 'business_demo',
 environment: config.environment || 'demo',
 channel,
 user_id: userId,
 display_name: ctx.display_name || 'Tester Demo'
};

const testCases = [
 {
   case_id: 'UC01',
   case_name: 'Entrada simple / saludo controlado',
   case_type: 'conversation_basic',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'hola'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     'product_recommended',
     'message_sent'
   ],
   expected_visible: {
     max_messages: 1,
     short_response: false,
     should_not_show_sku: true
   }
 },
 {
   case_id: 'UC02',
   case_name: 'Búsqueda y recomendación de producto',
   case_type: 'product_search',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'busco un cepillo de dientes ecológico'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     // ¡Adiós response_generated fantasma!
     'product_recommended',
     'message_sent'
   ],
   expected_visible: {
     should_recommend_catalog_products: true,
     max_options: 5,
     should_not_show_sku: true,
     should_not_invent_price: true,
     should_not_invent_stock: true
   }
 },
 {
   case_id: 'UC03',
   case_name: 'Producto concreto con imagen real',
   case_type: 'product_image',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'quiero ver el termo de bambú'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     // ¡Adiós response_generated fantasma!
     'message_sent',
     'image_sent'
   ],
   expected_visible: {
     image_required: true,
     fallback_allowed: false,
     should_not_show_sku: true
   }
 },
 {
   case_id: 'UC04',
   case_name: 'Comercio Accional Lite de punta a punta',
   case_type: 'commerce_lite',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'lo llevo'
     },
     {
       turn: 2,
       text: 'Me llamo Em, estoy en Bogotá y la entrega sería en la Calle 123'
     },
     {
       turn: 3,
       text: 'continuar'
     },
     {
       turn: 4,
       text: 'continuar con el pago demo'
     },
     {
       turn: 5,
       text: 'ya pagué'
     },
     {
       turn: 6,
       text: 'continuar con el envío'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     'message_sent'
   ],
   expected_visible: {
     should_create_transaction: true,
     should_capture_minimum_data: true,
     should_simulate_payment: true,
     should_confirm_demo_order: true,
     should_create_fake_tracking: true,
     should_clarify_demo_not_real_payment: true
   }
 },
 {
   case_id: 'UC05',
   case_name: 'Handoff humano básico',
   case_type: 'handoff_lite',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'quiero hablar con un asesor'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     'handoff_triggered',
     'handoff_human_notified',
     'message_sent'
   ],
   expected_visible: {
     should_create_handoff: true,
     should_notify_customer: true,
     should_notify_human_channel: true,
     should_not_use_technical_terms: true
   }
 }
];

return testCases.map(testCase => ({
 json: {
   validation_run: run,
   m11_config: config,
   test_case: {
     ...testCase,
     trace: commonTrace,
     context: commonContext,
     expected_correlation: {
       conversation_id: conversationId,
       session_id: sessionId,
       user_id: userId
     }
   }
 }
}));

const input = items[0]?.json || {};

const testCase = input.test_case || {};
const config = input.m11_config || {};

const executionMode = config.execution_mode || 'manual_evidence';

const executionPayload = {
 schema_version: 'dalia.m11.test_case_execution.v1',
 execution_mode: executionMode,

 test_case_id: testCase.case_id,
 test_case_name: testCase.case_name,
 case_type: testCase.case_type,

 trace: testCase.trace || {},
 context: testCase.context || {},

 turns: testCase.turns || [],

 expected_events: testCase.expected_events || [],
 expected_visible: testCase.expected_visible || {},

 validation_run_id: input.validation_run?.validation_run_id || ''
};

const manualInstructions = {
 channel: testCase.context?.channel || 'whatsapp',
 user_id: testCase.context?.user_id || '',
 messages_to_send: (testCase.turns || []).map(turn => turn.text),
 instruction:
   'Envía estos mensajes en el canal real respetando el orden. Luego deja que M11 consulte M8 para evaluar evidencia.'
};

return [
 {
   json: {
     ...input,
     test_execution: {
       prepared: true,
       execution_mode: executionMode,
       payload: executionPayload,
       manual_instructions: manualInstructions,
       prepared_at: new Date().toISOString()
     }
   }
 }
];

const input = items[0]?.json || {};

return [
 {
   json: {
     ...input,
     scenario_execution_result: {
       attempted: false,
       mode: 'manual_evidence',
       status: 'manual_execution_required',
       instructions: input.test_execution?.manual_instructions || {},
       note: 'Ejecuta manualmente los mensajes del caso y luego continúa la evaluación contra M8.'
     }
   }
 }
];

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function makeId(prefix) {
  const ts = Date.now();
  const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
  return `${prefix}_${ts}_${rand}`;
}

// 1. Curamos la amnesia: leemos toda la info de los 4 nodos anteriores
const caseContext = items[0]?.json || {};
const testCase = caseContext.test_case || {};
const run = caseContext.validation_run || {};

// 2. Leemos los logs desde su nueva ubicación (empaquetados por la Task 2)
const evidenceRows = caseContext.observability_evidence_rows || [];

const eventNames = evidenceRows.map(row => row.event_name);
const uniqueEventNames = [...new Set(eventNames)];
const expectedEvents = testCase.expected_events || [];

const missingEvents = expectedEvents.filter(eventName => {
  return !uniqueEventNames.includes(eventName);
});

const errorEvents = evidenceRows.filter(row => {
  return row.status === 'error' || row.level === 'ERROR';
});

const warnings = [];
const errors = [];

if (missingEvents.length > 0) {
  errors.push({
    code: 'missing_expected_events',
    detail: missingEvents
  });
}

if (errorEvents.length > 0) {
  warnings.push({
    code: 'error_events_found',
    detail: errorEvents.map(row => ({
      event_id: row.event_id,
      module: row.module,
      error_code: row.error_code,
      error_message: row.error_message
    }))
  });
}

// 3. Integramos las revisiones de Copy y Secuencia (Task 2)
const copyReview = caseContext.copy_rules_review || {};
const sequenceReview = caseContext.sequence_review || {};
const adjustmentBacklog = caseContext.copy_adjustment_backlog || {};

if (copyReview.status === 'failed') {
  errors.push({
    code: 'copy_rules_failed',
    detail: copyReview.findings || []
  });
} else if (copyReview.status === 'warning') {
  warnings.push({
    code: 'copy_rules_warning',
    detail: [
      ...(copyReview.findings || []),
      ...(copyReview.warnings || [])
    ]
  });
}

if (sequenceReview.status === 'failed') {
  errors.push({
    code: 'message_sequence_failed',
    detail: sequenceReview.findings || []
  });
} else if (sequenceReview.status === 'warning') {
  warnings.push({
    code: 'message_sequence_warning',
    detail: sequenceReview.warnings || []
  });
}

// 4. Calculamos el veredicto final
let status = 'passed';
if (errors.length > 0) {
  status = 'failed';
} else if (warnings.length > 0) {
  status = 'warning';
}

const result = {
  validation_result_id: makeId('valres'),
  validation_run_id: run.validation_run_id,
  case_id: testCase.case_id,
  case_name: testCase.case_name,
  case_type: testCase.case_type,
  status,

  expected_result: {
    expected_events: expectedEvents,
    expected_visible: testCase.expected_visible || {},
    critical: Boolean(testCase.critical)
  },

  actual_result: {
    events_found: uniqueEventNames,
    logs_found: evidenceRows.length,
    error_events_count: errorEvents.length,
    missing_events: missingEvents,
    copy_review: copyReview,
    sequence_review: sequenceReview,
    adjustment_backlog: adjustmentBacklog
  },

  evidence: {
    conversation_id: testCase.expected_correlation?.conversation_id || '',
    session_id: testCase.expected_correlation?.session_id || '',
    user_id: testCase.expected_correlation?.user_id || '',
    events: evidenceRows.map(row => ({
      event_id: row.event_id,
      timestamp: row.timestamp,
      module: row.module,
      event_name: row.event_name,
      event_type: row.event_type,
      status: row.status,
      level: row.level,
      transaction_id: row.transaction_id,
      handoff_id: row.handoff_id,
      error_code: row.error_code
    }))
  },

  observability_query: {
    table: 'dalia_observability_events_lite',
    filter: {
      session_id: testCase.expected_correlation?.session_id || '',
      user_id: testCase.expected_correlation?.user_id || ''
    }
  },

  errors,
  warnings
};

return [
  {
    json: {
      ...caseContext,
      test_case_result: result
    }
  }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function asArray(value) {
 return Array.isArray(value) ? value : [];
}

function safePayload(row) {
 const payload = row.payload || {};
 if (typeof payload === 'object') return payload;

 try {
   return JSON.parse(payload);
 } catch (e) {
   return {};
 }
}

function getTextPreview(row) {
 const payload = safePayload(row);

 return clean(
   payload.visible_text_preview ||
   payload.replyText ||
   payload.reply_text ||
   payload.message_text ||
   payload.text ||
   payload.customer_notification_text ||
   ''
 );
}

function inferVisibleUnit(row) {
 const payload = safePayload(row);

 if (row.event_name === 'image_sent') {
   return {
     type: 'image',
     event_id: row.event_id,
     timestamp: row.timestamp,
     module: row.module,
     status: row.status,
     source: payload.image_source || payload.source || ''
   };
 }

 if (row.event_name === 'message_sent') {
   const units = asArray(payload.visible_units);

   if (units.length > 0) {
     return units.map(unit => ({
       type: clean(unit.type || 'text'),
       event_id: row.event_id,
       timestamp: row.timestamp,
       module: row.module,
       status: row.status
     }));
   }

   if (payload.image_sent && payload.text_sent) {
     return [
       {
         type: 'text',
         event_id: row.event_id,
         timestamp: row.timestamp,
         module: row.module,
         status: row.status
       },
       {
         type: 'image',
         event_id: row.event_id,
         timestamp: row.timestamp,
         module: row.module,
         status: row.status
       }
     ];
   }

   if (payload.image_sent) {
     return {
       type: 'image',
       event_id: row.event_id,
       timestamp: row.timestamp,
       module: row.module,
       status: row.status
     };
   }

   return {
     type: 'text',
     event_id: row.event_id,
     timestamp: row.timestamp,
     module: row.module,
     status: row.status
   };
 }

 if (row.event_name === 'response_generated') {
   return {
     type: 'generated_response',
     event_id: row.event_id,
     timestamp: row.timestamp,
     module: row.module,
     status: row.status
   };
 }

 return null;
}

const caseContext = $('Prepare Test Case Execution').first().json || {};
const testCase = caseContext.test_case || {};

const evidenceRows = items
 .map(item => item.json || {})
 .filter(row => row.event_name)
 .sort((a, b) => new Date(a.timestamp || 0) - new Date(b.timestamp || 0));

const visibleRelevantRows = evidenceRows.filter(row =>
 [
   'response_generated',
   'product_recommended',
   'message_sent',
   'image_sent',
   'delivery_failed'
 ].includes(row.event_name)
);

const visibleTexts = visibleRelevantRows
 .map(row => {
   const text = getTextPreview(row);

   if (!text) return null;

   return {
     event_id: row.event_id,
     event_name: row.event_name,
     module: row.module,
     timestamp: row.timestamp,
     text
   };
 })
 .filter(Boolean);

const visibleUnitsRaw = visibleRelevantRows
 .map(inferVisibleUnit)
 .filter(Boolean)
 .flat();

const visibleSequence = visibleUnitsRaw
 .filter(unit => ['text', 'image', 'generated_response'].includes(unit.type))
 .map(unit => ({
   type: unit.type,
   event_id: unit.event_id,
   timestamp: unit.timestamp,
   module: unit.module,
   status: unit.status
 }));

const evidenceQuality =
 visibleTexts.length > 0 || visibleSequence.length > 0
   ? 'usable'
   : 'insufficient';

return [
 {
   json: {
     ...caseContext,
     observability_evidence_rows: evidenceRows,
     visible_transcript_review: {
       case_id: testCase.case_id,
       case_name: testCase.case_name,
       visible_texts: visibleTexts,
       visible_sequence: visibleSequence,
       events_found: [...new Set(evidenceRows.map(row => row.event_name))],
       evidence_quality: evidenceQuality,
       reviewed_at: new Date().toISOString()
     }
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function normalize(value) {
 return clean(value)
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g, '');
}

function includesAny(text, terms) {
 const normalized = normalize(text);
 return terms.some(term => normalized.includes(normalize(term)));
}

function hasSkuLikePattern(text) {
 const value = clean(text);

 const patterns = [
   /\bSKU[-_\s]?[A-Z0-9]{3,}\b/i,
   /\bYE[-_\s]?\d{4,}\b/i,
   /\b[A-Z]{2,}[-_]\d{3,}\b/i
 ];

 return patterns.some(pattern => pattern.test(value));
}

const input = items[0]?.json || {};
const testCase = input.test_case || {};
const review = input.visible_transcript_review || {};
const expectedVisible = testCase.expected_visible || {};

const texts = Array.isArray(review.visible_texts)
 ? review.visible_texts
 : [];

const allText = texts.map(item => item.text).join('\n');

const findings = [];
const warnings = [];

const forbiddenTerms = [
 'n8n',
 'qdrant',
 'rag',
 'workflow',
 'subworkflow',
 'módulo',
 'modulo',
 'herramienta interna',
 'base vectorial',
 'prompt',
 'llm',
 'json',
 'schema'
];

if (review.evidence_quality === 'insufficient') {
 warnings.push({
   code: 'insufficient_visible_copy_evidence',
   detail: 'No se encontró texto visible suficiente en los logs M8. Revisa que M7 esté registrando visible_text_preview.'
 });
}

if (includesAny(allText, forbiddenTerms)) {
 findings.push({
   severity: 'failed',
   code: 'internal_or_technical_terms_visible',
   detail: 'El copy visible contiene términos técnicos o internos.'
 });
}

if (hasSkuLikePattern(allText)) {
 findings.push({
   severity: 'failed',
   code: 'sku_visible_to_customer',
   detail: 'El texto visible parece exponer SKU o códigos internos.'
 });
}

for (const item of texts) {
 if (item.text.length > 700) {
   findings.push({
     severity: 'warning',
     code: 'message_too_long',
     detail: `El mensaje ${item.event_id} supera 700 caracteres.`
   });
 }
}

if (testCase.case_id === 'UC01') {
 if (allText.length > 600) {
   findings.push({
     severity: 'warning',
     code: 'greeting_response_too_long',
     detail: 'El saludo debería responderse de forma breve.'
   });
 }
}

if (testCase.case_id === 'UC02') {
 if (!review.events_found?.includes('product_recommended')) {
   findings.push({
     severity: 'failed',
     code: 'product_recommendation_not_visible',
     detail: 'La búsqueda de producto debería generar recomendación basada en catálogo.'
   });
 }

 if (expectedVisible.max_options) {
   const productEvent = input.observability_evidence_rows?.find(row => row.event_name === 'product_recommended');
   const payload = productEvent?.payload || {};
   const itemsCount = Number(payload.items_count || payload.catalog_items_count || 0);

   if (itemsCount > Number(expectedVisible.max_options)) {
     findings.push({
       severity: 'failed',
       code: 'too_many_product_options',
       detail: `Se encontraron ${itemsCount} opciones; máximo esperado: ${expectedVisible.max_options}.`
     });
   }
 }
}

// Bloques UC04 y UC05 eliminados para relajar al auditor ✂️

const hasFailure = findings.some(finding => finding.severity === 'failed');
const hasWarning =
 warnings.length > 0 ||
 findings.some(finding => finding.severity === 'warning');

const status = hasFailure
 ? 'failed'
 : hasWarning
   ? 'warning'
   : 'passed';

return [
 {
   json: {
     ...input,
     copy_rules_review: {
       status,
       findings,
       warnings,
       text_count: texts.length,
       reviewed_at: new Date().toISOString()
     }
   }
 }
];

const input = items[0]?.json || {};
const testCase = input.test_case || {};
const review = input.visible_transcript_review || {};

const expectedVisible = testCase.expected_visible || {};
const visibleSequence = Array.isArray(review.visible_sequence)
 ? review.visible_sequence
 : [];

const sequenceTypes = visibleSequence.map(unit => unit.type);

const findings = [];
const warnings = [];

if (review.evidence_quality === 'insufficient') {
 warnings.push({
   code: 'insufficient_sequence_evidence',
   detail: 'No hay evidencia suficiente para validar secuencia visible.'
 });
}

if (
 Array.isArray(expectedVisible.sequence) &&
 expectedVisible.sequence.length > 0
) {
 const expected = expectedVisible.sequence;

 const simplifiedActual = sequenceTypes.filter(type =>
   expected.includes(type)
 );

 const actualStartsCorrectly =
   expected.every((expectedType, index) => simplifiedActual[index] === expectedType);

 if (!actualStartsCorrectly) {
   findings.push({
     severity: 'failed',
     code: 'visible_sequence_mismatch',
     detail: {
       expected,
       actual: simplifiedActual
     }
   });
 }
}

if (testCase.case_id === 'UC03') {
 const textIndex = sequenceTypes.indexOf('text');
 const imageIndex = sequenceTypes.indexOf('image');

 if (imageIndex === -1 && expectedVisible.image_required) {
   findings.push({
     severity: 'failed',
     code: 'image_not_sent_for_product_case',
     detail: 'El caso de producto concreto esperaba imagen real.'
   });
 }

 if (textIndex === -1) {
   findings.push({
     severity: 'failed',
     code: 'text_not_sent_before_image',
     detail: 'El caso de producto con imagen debe enviar texto visible.'
   });
 }

 if (textIndex >= 0 && imageIndex >= 0 && imageIndex < textIndex) {
   findings.push({
     severity: 'failed',
     code: 'image_sent_before_text',
     detail: 'La imagen fue enviada antes del texto.'
   });
 }
}

const hasFailure = findings.some(finding => finding.severity === 'failed');
const hasWarning = warnings.length > 0;

const status = hasFailure
 ? 'failed'
 : hasWarning
   ? 'warning'
   : 'passed';

return [
 {
   json: {
     ...input,
     sequence_review: {
       status,
       sequence_types: sequenceTypes,
       findings,
       warnings,
       reviewed_at: new Date().toISOString()
     }
   }
 }
];

const input = items[0]?.json || {};

const testCase = input.test_case || {};
const copyReview = input.copy_rules_review || {};
const sequenceReview = input.sequence_review || {};

const allFindings = [
 ...(copyReview.findings || []),
 ...(copyReview.warnings || []).map(w => ({ severity: 'warning', ...w })),
 ...(sequenceReview.findings || []),
 ...(sequenceReview.warnings || []).map(w => ({ severity: 'warning', ...w }))
];

const backlog = [];

for (const finding of allFindings) {
 const code = finding.code || '';

 if (code.includes('sku_visible')) {
   backlog.push({
     target_module: 'M3/M7',
     priority: 'high',
     action: 'Ajustar post-procesamiento para eliminar SKU o códigos internos del texto visible.',
     finding_code: code
   });
 }

 if (code.includes('internal_or_technical_terms')) {
   backlog.push({
     target_module: 'M3/M6/M7',
     priority: 'high',
     action: 'Ajustar plantillas y prompts para evitar términos técnicos visibles al cliente.',
     finding_code: code
   });
 }

 if (code.includes('message_too_long') || code.includes('greeting_response_too_long')) {
   backlog.push({
     target_module: 'M3/M7',
     priority: 'medium',
     action: 'Reducir longitud del copy y reforzar respuesta breve por tipo de intención.',
     finding_code: code
   });
 }

 if (code.includes('catalog_used_in_greeting')) {
   backlog.push({
     target_module: 'M2/M3',
     priority: 'high',
     action: 'Revisar clasificación de saludo y evitar recuperación de catálogo en general_inquiry/greeting puro.',
     finding_code: code
   });
 }

 if (code.includes('product_recommendation_not_visible')) {
   backlog.push({
     target_module: 'M3',
     priority: 'high',
     action: 'Revisar recuperación y normalización de catálogo para asegurar recomendación visible.',
     finding_code: code
   });
 }

 if (code.includes('too_many_product_options')) {
   backlog.push({
     target_module: 'M3',
     priority: 'medium',
     action: 'Aplicar límite máximo de opciones de producto en respuesta visible.',
     finding_code: code
   });
 }

 if (code.includes('commerce_demo_clarity_missing')) {
   backlog.push({
     target_module: 'M5/M7',
     priority: 'medium',
     action: 'Ajustar copy de comercio para aclarar que pago, orden o tracking son simulados en demo.',
     finding_code: code
   });
 }

 if (code.includes('handoff_transfer_message_not_clear')) {
   backlog.push({
     target_module: 'M6',
     priority: 'medium',
     action: 'Ajustar mensaje de transferencia para indicar continuidad con persona del equipo y contexto compartido.',
     finding_code: code
   });
 }

 if (
   code.includes('visible_sequence_mismatch') ||
   code.includes('image_sent_before_text') ||
   code.includes('text_not_sent_before_image')
 ) {
   backlog.push({
     target_module: 'M7',
     priority: 'high',
     action: 'Corregir orquestación visible para asegurar secuencia texto → imagen.',
     finding_code: code
   });
 }

 if (code.includes('image_not_sent_for_product_case')) {
   backlog.push({
     target_module: 'M7',
     priority: 'high',
     action: 'Revisar recuperación de imagen desde Google Drive y fallback de producto concreto.',
     finding_code: code
   });
 }

 if (code.includes('insufficient')) {
   backlog.push({
     target_module: 'M8/M7',
     priority: 'medium',
     action: 'Agregar evidencia visible mínima en payload de M8: visible_text_preview, visible_units y sequence_observed.',
     finding_code: code
   });
 }
}

const deduped = [];
const seen = new Set();

for (const item of backlog) {
 const key = `${item.target_module}|${item.action}|${item.finding_code}`;
 if (seen.has(key)) continue;
 seen.add(key);
 deduped.push(item);
}

const status =
 allFindings.some(f => f.severity === 'failed')
   ? 'failed'
   : allFindings.length > 0
     ? 'warning'
     : 'passed';

return [
 {
   json: {
     ...input,
     copy_adjustment_backlog: {
       status,
       items: deduped,
       total_items: deduped.length,
       built_at: new Date().toISOString()
     }
   }
 }
];
